<?php
$role=current_user()['role'];
if($role==='guru' && !isset($_GET['id']) && !ak_one('SELECT id FROM ak_wali_kelas WHERE id_guru=? AND aktif=1 LIMIT 1',[user_reference()])){echo '<div class="panel"><p>Rekap nilai tersedia sesuai mapel yang diampu. Pemeriksaan rapor semester memerlukan penugasan wali kelas.</p><a class="button" href="'.e(ak_link('nilai')).'">Buka rekap nilai mapel</a></div>';return;}
require_role('admin','kepala_sekolah','siswa','guru');
$periodId=isset($_GET['id_tahun_ajaran'])?input_id($_GET,'id_tahun_ajaran'):(int)active_period()['id_tahun_ajaran'];
if(isset($_GET['id'])) {
    $report=ak_report(input_id($_GET,'id'));$payload=$report['payload'];
    ?><section class="panel"><p class="eyebrow">RAPOR SEMESTER · <?=e($report['status'])?> · VERSI <?=e($report['versi'])?></p><h2><?=e($payload['siswa']['nama'])?></h2><p>NIS <?=e($report['nis'])?> · <?=e($payload['siswa']['kelas'])?> · <?=e($payload['periode']['tahun_ajaran'])?> / <?=e($payload['periode']['semester'])?></p><p class="muted">Batas rekap: <?=e($payload['periode']['batas_rekap'])?>. Arsip snapshot tidak mengikuti perubahan nilai setelah dibuat.</p><div class="table-scroll"><table><thead><tr><th>Mata pelajaran</th><th>Nilai</th><th>Predikat</th><th>Aturan</th><th>Deskripsi</th></tr></thead><tbody><?php foreach($payload['nilai'] as $g):?><tr><td><?=e($g['nama_mapel'])?></td><td><?=e($g['nilai_akhir'])?></td><td><?=e($g['predikat'])?></td><td>v<?=e($g['versi_aturan'])?></td><td class="wrap"><?=e($g['deskripsi'])?></td></tr><?php endforeach;?></tbody></table></div><h3>Rekap kehadiran harian</h3><?php ak_summary_cards($payload['kehadiran_harian']);ak_exports('rapor',['id'=>$report['id']]);?><p class="muted">Hash arsip: <?=e($report['payload_hash'])?></p></section>
    <?php if($role!=='siswa')require __DIR__.'/homeroom_review.php';if($role==='admin' && $report['status']!=='ditarik'):?><section class="panel"><h2>Verifikasi / penerbitan</h2><form method="post"><?=csrf_field()?><?php ak_hidden('action','rapor_status');ak_hidden('id',$report['id']);ak_hidden('revision',$report['revision']);$choices=match($report['status']){'draft'=>['terverifikasi'=>'Tandai telah diverifikasi'],'terverifikasi'=>['diterbitkan'=>'Terbitkan kepada siswa','ditarik'=>'Tarik snapshot'],'diterbitkan'=>['ditarik'=>'Tarik penerbitan'],default=>[]};ak_select('status','Tindakan',$choices);ak_field('alasan','Alasan / bukti pemeriksaan');?><button type="submit">Simpan keputusan rapor</button></form></section><?php endif;return;
}
$periodOptions=[];
if($role==='siswa')$available=ak_rows("SELECT DISTINCT t.* FROM tahun_ajaran t JOIN ak_rapor_snapshot r USING(id_tahun_ajaran) JOIN ak_rapor_status s ON s.id_snapshot=r.id WHERE r.nis=? AND s.status='diterbitkan' ORDER BY t.id_tahun_ajaran DESC",[(string)user_reference()]);
else $available=ak_rows('SELECT t.* FROM tahun_ajaran t JOIN ak_periode p USING(id_tahun_ajaran) WHERE p.terverifikasi=1 ORDER BY t.id_tahun_ajaran DESC');
foreach($available as $p)$periodOptions[$p['id_tahun_ajaran']]=$p['tahun_ajaran'].' '.$p['semester'];
?><form method="get" class="panel form-grid filter"><?php ak_hidden('view','rapor');ak_select('id_tahun_ajaran','Tahun ajaran / semester',$periodOptions,$periodId);?><button class="secondary">Tampilkan periode</button></form><?php
$scope=$role==='siswa'?" AND r.nis=? AND s.status='diterbitkan'":'';$args=$role==='siswa'?[$periodId,user_reference()]:[$periodId];
if($role==='guru'){$scope.=" AND EXISTS(SELECT 1 FROM ak_wali_kelas w WHERE w.id_guru=? AND w.id_kelas=r.id_kelas AND w.id_tahun_ajaran=r.id_tahun_ajaran AND w.aktif=1 AND w.mulai<=JSON_UNQUOTE(JSON_EXTRACT(r.payload_json,'$.periode.batas_rekap')) AND w.selesai>=JSON_UNQUOTE(JSON_EXTRACT(r.payload_json,'$.periode.batas_rekap')))";$args[]=user_reference();}
$rows=ak_rows('SELECT r.id,r.nis,r.versi,r.created_at,s.status,x.nama_siswa FROM ak_rapor_snapshot r JOIN ak_rapor_status s ON s.id_snapshot=r.id JOIN siswa x ON x.nis=r.nis WHERE r.id_tahun_ajaran=?'.$scope.' ORDER BY r.id DESC LIMIT 200',$args);
?><section class="panel"><h2>Arsip rapor</h2><p>Hanya snapshot berstatus diterbitkan yang dapat dibaca siswa. Ketersediaan nilai atau flag publikasi lama tidak otomatis menerbitkan rapor.</p><?php if(!$rows):?><p>Belum ada rapor yang dapat ditampilkan pada periode ini.</p><?php endif;foreach($rows as $r):?><p><a class="button secondary" href="<?=e(ak_link('rapor',['id'=>$r['id']]))?>"><?=e($r['nama_siswa'])?> · v<?=e($r['versi'])?> · <?=e($r['status'])?></a></p><?php endforeach;?></section>
<?php if($role==='admin'):?><section class="panel"><h2>Buat snapshot rapor</h2><p>Semua nilai dari mata pelajaran yang ditugaskan harus lengkap. Snapshot baru dimulai sebagai draft dan memerlukan verifikasi sebelum diterbitkan.</p><form method="post"><?=csrf_field()?><?php ak_hidden('action','rapor_buat');$periods=[];foreach(ak_rows('SELECT * FROM tahun_ajaran ORDER BY id_tahun_ajaran DESC') as $p)$periods[$p['id_tahun_ajaran']]=$p['tahun_ajaran'].' '.$p['semester'];ak_select('id_tahun_ajaran','Periode',$periods,$periodId);$students=[];foreach(ak_rows("SELECT nis,nama_siswa FROM siswa WHERE status='aktif' ORDER BY nama_siswa") as $s)$students[$s['nis']]=$s['nis'].' · '.$s['nama_siswa'];ak_select('nis','Siswa',$students);ak_field('tanggal','Batas rekap',date('Y-m-d'),'date');ak_field('alasan','Dasar pembuatan snapshot');?><button type="submit">Buat draft snapshot</button></form></section><?php endif;?>
